use llmgw::{autostart::{Platform,RegistrationSpec,RegistrationPlan,Action,RegistrationState,login_auth_availability},config::Auth};
use std::{path::Path,fs};
fn root()->std::path::PathBuf{Path::new(env!("REVIEW_OUT")).join("rust-owned")}
#[test]fn current_user_sid_both_fields_and_plan_hash(){let r=root();fs::create_dir_all(&r).unwrap();let exe=Path::new(r"C:\Tools\llmgw.exe");let cfg=Path::new(r"C:\Users\테스트 & 파일\gateway.toml");let p=RegistrationPlan::prepare_for_windows_user(exe,cfg,&r,Action::On,"S-1-5-21-1-2-3-1001").unwrap();let q=RegistrationPlan::prepare_for_windows_user(exe,cfg,&r,Action::On,"S-1-5-21-1-2-3-1002").unwrap();assert_eq!(p.spec().definition().matches("<UserId>S-1-5-21-1-2-3-1001</UserId>").count(),2);assert_ne!(p.preview_hash(),q.preview_hash());assert_eq!(p.state(),RegistrationState::Blocked);assert!(!p.registration_absent());assert!(p.apply().is_err());assert!(!p.target_path().exists());}
#[test]fn unknown_env_auth_without_login_observation(){assert_eq!(login_auth_availability(&Auth::Env{header:"authorization".into(),name:"REVIEW_SYNTHETIC_AUTH".into()}).to_string(),"unknown");}
#[test]fn windows_percent_refused_for_either_path(){for (e,c) in [(r"C:\%USERNAME%\llmgw.exe",r"C:\config.toml"),(r"C:\llmgw.exe",r"C:\literal%\config.toml")]{let error=RegistrationSpec::new_for_windows_user(Path::new(e),Path::new(c),"S-1-5-21-1-2-3-1001").unwrap_err();assert!(error.to_string().contains("percent paths"));}}
#[test]fn unix_templates_preserve_native_grammar(){let exe=Path::new("/fixture 한글 & $100%/llmgw");let cfg=Path::new("/fixture 한글 & $100%/config \\\"<>&.toml");let m=RegistrationSpec::new(Platform::Macos,exe,cfg).unwrap();let l=RegistrationSpec::new(Platform::Linux,exe,cfg).unwrap();assert!(m.definition().contains("<key>KeepAlive</key>\n<false/>"));assert!(l.definition().contains("ExecStart=:\""));assert!(l.definition().contains("$100%%"));assert!(l.definition().contains("Restart=no"));}
#[test]fn mac_reviewed_snapshot_refuses_intervening_change(){let r=root().join("snapshot");fs::create_dir_all(&r).unwrap();let e=r.join("llmgw");let c=r.join("config");fs::write(&e,b"fixture").unwrap();fs::write(&c,b"fixture").unwrap();let p=RegistrationPlan::prepare(Platform::Macos,&e,&c,&r,Action::On).unwrap();assert!(p.registration_absent());p.apply().unwrap();let off=RegistrationPlan::prepare(Platform::Macos,&e,&c,&r,Action::Off).unwrap();fs::write(off.target_path(),b"foreign content").unwrap();assert!(off.apply().is_err());assert_eq!(fs::read(off.target_path()).unwrap(),b"foreign content");}
